Create Table Emp_Recr                         -- التوظيف
( Id         BIGINT NOT NULL,                     -- مفتاح رئيسي
  Num        INTEGER,                              -- الرقم
  dDate      TIMESTAMP,                                   -- التاريخ
  SDate      TIMESTAMP,                                   -- تاريخ بداية الإعلان
  EDate      TIMESTAMP,                                   -- تاريخ نهاية الإعلان
  Code       VARCHAR(25),                      -- الرمز
  Name       VARCHAR(250),                     -- الاسم
  GenInfo    VARCHAR(1024),                    -- General Information معلومات عامة
  PosPurp    VARCHAR(1024),                    -- Position Purpose المنصب المستهدف
  EssenFunc  VARCHAR(1024),                    -- Essential Functions الوظائف الأساسية
  MinReq     VARCHAR(1024),                    -- Minimum Requirements الحد الأدنى من المتطلبات
  PrefQlfy   VARCHAR(1024),                    -- Preferred Qualifications المؤهلات المفضلة
  Ins_User   BIGINT, Ins_Date TIMESTAMP,
  Upd_User   BIGINT, Upd_Date TIMESTAMP,
  CONSTRAINT Emp_Recr_PK        PRIMARY KEY (Id)
);

CREATE SEQUENCE IF NOT EXISTS EMP_APPL_seq
  INCREMENT BY 1
  START WITH 1;

Create Table Emp_Appl                         -- طلبات التوظيف
( Id           BIGINT NOT NULL,                   -- مفتاح رئيسي
  Recr_Id      BIGINT NOT NULL,                   -- مفتاح الأب
  Num          INTEGER,                            -- رقم الطلب
  dDate        TIMESTAMP Default LOCALTIMESTAMP,                 -- تاريخ الطلب
  Name         VARCHAR(100) NOT NULL,          -- الاسم
  Father       VARCHAR(50),                    -- الأب
  Mother       VARCHAR(50),                    -- الأم
  PBirth       VARCHAR(100),                   -- مكان الولادة
  DBirth       TIMESTAMP,                                 -- تاريخ الولادة
  NatNum       VARCHAR(30),                    -- الرقم الوطني
  Kied         VARCHAR(30),                    -- محل و رقم القيد
  Phone        VARCHAR(50),                    -- هاتف
  Mobile       VARCHAR(50),                    -- موبايل
  EMail        VARCHAR(50),                    -- البريد الإلكتروني
  Address      VARCHAR(512),                   -- عنوان
  Gender_Id    BIGINT Default 1,                  -- الجنس
  Military_Id  BIGINT Default 1,                  -- خدمة العلم
  Martial_Id   BIGINT Default 0,                  -- الحالة الإجتماعية
  Nat_Id       BIGINT Default 0,                  -- الجنسية
  Status_Id    BIGINT Default 0,                  -- حالة الطلب
  Result_Id    BIGINT Default 0,                  -- النتيجة
  ReqSal       NUMERIC(25,3) Default 0,               -- الراتب المطلوب
  Language_Id  BIGINT Default 0,                  -- علامة اختبار اللغة
  Computer_Id  BIGINT Default 0,                  -- علامة اختبار الكمبيوتر
  Technical_Id BIGINT Default 0,                  -- علامة اختبار تقني
  Interview_Id BIGINT Default 0,                  -- علامة المقابلة
  Rem          VARCHAR(250),                   -- ملاحظات
  Ins_User     BIGINT, Ins_Date TIMESTAMP,
  Upd_User     BIGINT, Upd_Date TIMESTAMP,
  CONSTRAINT Emp_App_PK           PRIMARY KEY (Id),
  CONSTRAINT Emp_App_Num          UNIQUE      (Num)
);

