  St1M           SMALLINT Default 0,                 -- دقيقة بدء دوام الفترة الأولى
  Ed1H           SMALLINT Default 0,                 -- ساعة نهاية دوام الفترة الأولى
  Ed1M           SMALLINT Default 0,                 -- دقيقة نهاية دوام الفترة الأولى
  L1H            SMALLINT Default 0,                 -- مجال التأخير ساعة الفترة الأولى
  L1M            SMALLINT Default 0,                 -- مجال التأخير دقيقة الفترة الأولى
  L1MRound       SMALLINT Default 0,                 -- دقائق مجال جبر التأخير للدخول الأول
  E1H            SMALLINT Default 0,                 -- مجال الخروج ساعة الفترة الأولى
  E1M            SMALLINT Default 0,                 -- مجال الخروج دقيقة الفترة الأولى
  St2H           SMALLINT Default 0,                 -- ساعة بدء دوام الفترة الثانية
  St2M           SMALLINT Default 0,                 -- دقيقة بدء دوام الفترة الثانية
  Ed2H           SMALLINT Default 0,                 -- ساعة نهاية دوام الفترة الثانية
  Ed2M           SMALLINT Default 0,                 -- دقيقة نهاية دوام الفترة الثانية
  L2H            SMALLINT Default 0,                 -- مجال التأخير ساعة الفترة الثانية
  L2M            SMALLINT Default 0,                 -- مجال التأخير دقيقة الفترة الثانية
  L2MRound       SMALLINT Default 0,                 -- دقائق مجال جبر التأخير للدخول الثانية
  E2H            SMALLINT Default 0,                 -- مجال الخروج ساعة الفترة الثانية
  E2M            SMALLINT Default 0,                 -- مجال الخروج دقيقة الفترة الثانية
  FBH            SMALLINT Default 0,                 -- ساعة الإستراحة الإجبارية
  FBM            SMALLINT Default 0,                 -- دقيقة الإستراحة الإجبارية
  AddH           SMALLINT Default 0,                 -- عدد ساعات العمل المطلوب ليحسب الإضافي بعدها
  AddM           SMALLINT Default 0,                 -- عدد دقائق العمل المطلوب ليحسب الإضافي بعدها
  ZeroH          SMALLINT Default 0,                 -- ساعة الصفر
  ZeroM          SMALLINT Default 0,                 -- دقيقة الصفر
  REntH          SMALLINT Default 0,                 -- ساعة رفض الدخول المبكر قبل الدوام
  REntM          SMALLINT Default 0,                 -- دقيقة رفض الدخول المبكر قبل الدوام
  ROutH          SMALLINT Default 0,                 -- ساعة رفض الخروج المتأخر بعد الدوام
  ROutM          SMALLINT Default 0,                 -- دقيقة رفض الخروج المتأخر بعد الدوام
  ROMRound       SMALLINT Default 0,                 -- دقيقة جبر الخروج المتأخر بعد الدوام
  Ins_User       BIGINT, Ins_Date   TIMESTAMP,
