  START WITH 1;

Create Table Emp_Emp                             -- دليل العاملين
( Id             BIGINT NOT NULL,                  -- مفتاح رئيسي
  Num            VARCHAR(15),                   -- مفتاح العامل
  NNum           VARCHAR(15),                   -- الرقم الوطني
  PNum           VARCHAR(15),                   -- الرقم الذاتي
  INum           VARCHAR(15),                   -- الرقم التأميني
  AttNum         VARCHAR(15),                   -- الرقم في مراقبة الدوام
  PCard          VARCHAR(15),                   -- رقم الهوية
  Kied           VARCHAR(25),                   -- محل ورقم القيد
  Name           VARCHAR(100),                  -- الاسم
  aName          VARCHAR(100),                  -- الاسم عربي
  eName          VARCHAR(100),                  -- الاسم أجنبي
  Father         VARCHAR(50),                   -- الأب
  Mother         VARCHAR(50),                   -- الأم
  PBirth         VARCHAR(50),                   -- مكان الولادة
  DBirth         TIMESTAMP,                                -- تاريخ الولادة
  Addr           VARCHAR(100),                  -- عنوان
