  Phone2         VARCHAR(15),                   -- هاتف2
  Mobile1        VARCHAR(15),                   -- موبايل
  Mobile2        VARCHAR(15),                   -- موبايل
  Fax            VARCHAR(15),                   -- فاكس
  Ext            VARCHAR(5),                    -- رقم التحويلة
  EMail1         VARCHAR(50),                   -- البريد الإلكتروني
  EMail2         VARCHAR(50),                   -- البريد الإلكتروني
  EPerson        VARCHAR(50),                   -- في الطوارئ الإتصل بـ
  EPhone         VARCHAR(30),                   -- هاتف طوارئ
  Computer       VARCHAR(30),                   -- اسم الكمبيوتر
  Username       VARCHAR(30),                   -- اسم الدخول للشبكة
  BankAcc        VARCHAR(50),                   -- رقم الحساب في المصرف
  BankName       VARCHAR(100),                  -- الاسم في المصرف
  BankStatus_Id  BIGINT Default 2,                 -- حالة التوطين المصرفي
  Status_Id      BIGINT Default 1,                 -- حالة العامل \1 عادي\2 مستقيل\3 متوفى\4 طرد\5 فصل
  WStatus_Id     BIGINT Default 2,                 -- حالة الدوام \1 يسجل دوامه \2 معفى من تسجيل الدوام
  Military_Id    BIGINT Default 1,                 -- خدمة العلم
  isOwner_Id     BIGINT Default 2,                 -- هل العامل من أحد مالكي الشركة
  Lang_Id        BIGINT Default 0,                 -- اللغة
  Educat_Id      BIGINT Default 0,                 -- الحالة التعليمية - الشهادة
  Job_Id         BIGINT Default 0,                 -- المهنة - الوظيفة
  Dept_Id        BIGINT Default 0,                 -- الدائرة
  Sect_Id        BIGINT Default 0,                 -- القسم
  Level_Id       BIGINT Default 0,                 -- الفئة
  Loc_Id         BIGINT Default 0,                 -- موقع المكتب
  Spc1_Id        BIGINT Default 0,                 -- تصنيف1
  Spc2_Id        BIGINT Default 0,                 -- تصنيف2
  Spc3_Id        BIGINT Default 0,                 -- تصنيف3
  Spc4_Id        BIGINT Default 0,                 -- تصنيف4
  Gender_Id      BIGINT Default 1,                 -- الجنس
  Nat_Id         BIGINT Default 0,                 -- الجنسية
  Martial_Id     BIGINT Default 0,                 -- الحالة الإجتماعية
  Child          SMALLINT Default 0,                 -- عدد الأطفال
  Wife_Id        BIGINT Default 2,                 -- حالة الزوجة
  IFamily_Id     BIGINT Default 2,                 -- التأمين العائلي Family Insurance
  IHelth_Id      BIGINT Default 2,                 -- التأمين الصحي Helth Insurance
  IChild         SMALLINT Default 2,                 -- عدد أولاد التأمين الصحي No of Covered Child
  Director_Id    BIGINT,                           -- المدير Director
  Manager_Id     BIGINT,                           -- المدير Manager
  FAppraisal_Id  BIGINT,                           -- First Appraisal
  SAppraisal_Id  BIGINT,                           -- Second Appraisal
  User_Id        BIGINT,                           -- المستخدم المرتب بالعامل \ اسم الدخول للنظام إن وجد
  Acr_Id         BIGINT,                           -- معتمد الرواتب
  WGrp_Id        BIGINT,                           -- مجموعة الدوام
  SGrp_Id        BIGINT,                           -- مجموعة الرواتب
  Appr_Id        BIGINT,                          -- قالب التقييم
  TGrad_Id       BIGINT,                          -- مفتاح الدرجة الوظيفية
  GradCons       INTEGER Default 0,                 -- أيام مكافآت القدم
  GradPuns       INTEGER Default 0,                 -- أيام عقوبة تأخير الترفيع
  GradDays       INTEGER Default 0,                 -- الخبرة الأيام
  GradSDate      TIMESTAMP,                                -- تاريخ بداية الدرجة الحالية
  CSDate         TIMESTAMP,                                -- تاريخ بداية العقد
  CEDate         TIMESTAMP,                                -- تاريخ نهاية العقد
  SDate          TIMESTAMP,                                -- تاريخ المباشرة
  Idate          TIMESTAMP,                                -- تاريخ التسجيل في التأمينات
  EDate          TIMESTAMP,                                -- تاريخ الإنتهاء من العمل\أي ترك العمل
  BaseSal        NUMERIC(25,3) Default 0,              -- الراتب الأساس
  FinanceSal     NUMERIC(25,3) DEfault 0,              -- الراتب المالي
  InsurSal       NUMERIC(25,3) DEfault 0,              -- الراتب التأميني
  Years          NUMERIC(7,3) Default 0,               -- سنوات الخبرة Years of Services
  VacDays        SMALLINT Default 0,                 -- الإجازات أيام
  VacHours       SMALLINT Default 0,                 -- الإجازات ساعات
  VacBDays       SMALLINT Default 0,                 -- رصيد الإجازات أيام
  VacBHours      SMALLINT Default 0,                 -- رصيد الإجازات ساعات
  Img            VARCHAR(250),                  -- الصورة الشخصية
  Rem            VARCHAR(250),                  -- ملاحظات
  Ins_User       BIGINT, Ins_Date TIMESTAMP,
  Upd_User       BIGINT, Upd_Date TIMESTAMP,
  CONSTRAINT     Emp_Emp_PK            PRIMARY KEY (Id  ),
  CONSTRAINT     Emp_Emp_Num           UNIQUE      (Num ),
  CONSTRAINT     Emp_Emp_NNum          UNIQUE      (NNum),
  CONSTRAINT     Emp_Emp_PNum          UNIQUE      (PNum),
  CONSTRAINT     Emp_Emp_INum          UNIQUE      (INum),
  CONSTRAINT     Emp_Emp_AttNum        UNIQUE      (AttNum),
  CONSTRAINT     Emp_Emp_NFM           UNIQUE      (Name, Father, Mother)
);

