  Loan_Id     BIGINT,                             -- مفتاح السلفة
  Amt         NUMERIC(25,3) Default 0,                 -- المبلغ
  Num         INTEGER,                              -- الرقم
  dDate       TIMESTAMP Default LOCALTIMESTAMP,                   -- التاريخ
  Rem         VARCHAR(100),                     -- ملاحظات
  Ins_User    BIGINT, Ins_Date   TIMESTAMP,
  Upd_User    BIGINT, Upd_Date   TIMESTAMP,
  Constraint  Emp_PLoan_PK       Primary Key (Id ),
  Constraint  Emp_PLoan_Num_UK   Unique      (Num)
);

CREATE SEQUENCE IF NOT EXISTS Emp_Sal_Seq
  INCREMENT BY 1
  START WITH 1;

Create Table Emp_Sal                 -- احتساب الرواتب
( Id          BIGINT,                             -- مفتاح رئيسي
  nYear       SMALLINT Default 0,                    -- السنة
  nMonth      SMALLINT Default 0,                    -- الشهر
  Status_Id   BIGINT Default 0,                    -- الحالة 0 قيد التحضير \ 1 تم الاحتساب دون اعتماد النتائج \ 2 تم اعتماد احتساب الرواتب
  Rem         VARCHAR(100),                     -- ملاحظات
  Ins_User    BIGINT, Ins_Date TIMESTAMP,
  Upd_User    BIGINT, Upd_Date TIMESTAMP,
  Constraint  Emp_Sal_PK        Primary Key (Id),
  Constraint  Emp_Sal_UK        UNIQUE      (nYear, nMonth)
);

CREATE SEQUENCE IF NOT EXISTS EMP_SALATT_seq
  INCREMENT BY 1
  START WITH 1;

Create Table Emp_SalAtt                    -- ملخص الدوام
( Id            BIGINT,                           -- مفتاح رئيسي
  Sal_Id        BIGINT NOT NULL,                  -- مفتاح الشهر ضمن السنة
  Emp_Id        BIGINT NOT NULL,                   -- مفتاح العامل
  DAdd          INTEGER Default 0,                  -- الإضافي النهاري
  NAdd          INTEGER Default 0,                  -- الإضافي الليلي
  WAdd          INTEGER Default 0,                  -- الإضافي نهاية الاسبوع
  HAdd          INTEGER Default 0,                  -- الإضافي عطلة
  nAbs          INTEGER Default 0,                  -- الغياب
  nSik70        INTEGER Default 0,                  -- المرض
  nSik80        INTEGER Default 0,                  -- المرض
  nDel          INTEGER Default 0,                  -- التأخير
  nPar          INTEGER Default 0,                  -- الأمومة
  nNPay         INTEGER Default 0,                  -- دون أجر
  Rem           VARCHAR(100),                   -- ملاحظات
  Ins_User      BIGINT, Ins_Date TIMESTAMP,
