  Constraint    Emp_SalAtt_PK     Primary Key (Id),
  Constraint    Emp_SalAtt_Emp_UK UNIQUE      (Sal_Id, Emp_Id)
);

CREATE SEQUENCE IF NOT EXISTS emp_SalCalc_seq
  INCREMENT BY 1
  START WITH 1;

Create Table Emp_SalCalc                    -- جدول احتساب الرواتب
( Id              BIGINT,                         -- مفتاح رئيسي
  Sal_Id          BIGINT NOT NULL,                -- مفتاح الشهر ضمن السنة
  Session_Id      BIGINT,                         -- مفتاح العملية
  Emp_Id          BIGINT NOT NULL,                 -- العامل
  Sal             NUMERIC(25,3) Default 0,             -- الراتب
  FSal            NUMERIC(25,3) Default 0,             -- الراتب المالي
  Tam             NUMERIC(25,3) Default 0,             -- الراتب التأميني
  WSal            NUMERIC(25,3) Default 0,             -- الراتب حسب الدوام
  TaxableSal      NUMERIC(25,3) Default 0,             -- الراتب الضريبي
  Net             NUMERIC(25,3) Default 0,             -- صافي الراتب
  nRound          NUMERIC(25,3) Default 0,             -- القيمة المدورة لأقرب 50
  GETam           NUMERIC(25,3) Default 0,             -- حصة العامل من التأمينات الإجتماعية
  GBTam1          NUMERIC(25,3) Default 0,             -- نسبة حصة رب العمل من التأمينات الإجتماعية 1
  GBTam2          NUMERIC(25,3) Default 0,             -- نسبة حصة رب العمل من التأمينات الإجتماعية 2
  GBTam3          NUMERIC(25,3) Default 0,             -- نسبة حصة رب العمل من التأمينات الإجتماعية 3
  GAETam          NUMERIC(25,3) Default 0,             -- مبلغ التأمينات - حصة العامل - المبلغ الذي سيحسم الراتب المقطوع والذي سينتج عنه الراتب الذي سيتم احتساب الضريبة بناءا عليه
  GABTam1         NUMERIC(25,3) Default 0,             -- مبلغ التأمينات - حصة رب العمل 1
  GABTam2         NUMERIC(25,3) Default 0,             -- مبلغ التأمينات - حصة رب العمل 2
  GABTam3         NUMERIC(25,3) Default 0,             -- مبلغ التأمينات - حصة رب العمل 3
  GTamStatus_Id   BIGINT Default 1,                -- حالة التأمينات \ 1 يدفعها العامل \ 2 يدفعها رب العمل
  GTaxStatus_Id   BIGINT Default 1,                -- حالة الضريبة \ 1 يدفعها العامل \ 2 يدفعها رب العمل
  GTaxFree        NUMERIC(25,3) Default 0,             -- الحد الأدنى المعفى من الضريبة بعد حسم التأمينات
  GTax            NUMERIC(25,3) Default 0,             -- الضريبة
  Comp            NUMERIC(25,3) Default 0,             -- التعويضات الدائمة
  Ded             NUMERIC(25,3) Default 0,             -- الحسميات الدائمة
  AddAdd          NUMERIC(25,3) Default 0,             -- الإضافة على الإضافي
  AddSal          NUMERIC(25,3) Default 0,             -- الإضافة على الراتب
  SubAdd          NUMERIC(25,3) Default 0,             -- الحسم من الإضافي
  SubSal          NUMERIC(25,3) Default 0,             -- الحسم من الراتب
  Cons            NUMERIC(25,3) Default 0,             -- المكافآت
  SalCons         NUMERIC(25,3) Default 0,             -- الإضافات على الراتب
  AddCons         NUMERIC(25,3) Default 0,             -- الإضافات على الإضافي
  Pun             NUMERIC(25,3) Default 0,             -- العقوبات
  SalPun          NUMERIC(25,3) Default 0,             -- الحسميات من الراتب
  AddPun          NUMERIC(25,3) Default 0,             -- الحسميات من الإضافي
  Dbt             NUMERIC(25,3) Default 0,             -- استجرارات
  Loan            NUMERIC(25,3) Default 0,             -- سلف
  NAddPrice       NUMERIC(7,3) Default 0,              -- نسبة  الإضافي الليلي
  DAddPrice       NUMERIC(7,3) Default 0,              -- نسبة الإضافي النهاري
  WAddPrice       NUMERIC(7,3) Default 0,              -- نسبة الإضافي عطلة نهاية الاسبوع
  HAddPrice       NUMERIC(7,3) Default 0,              -- نسبة الإضافي عطلة
  DAdd            INTEGER Default 0,                -- دقائق الإضافي النهاري
  NAdd            INTEGER Default 0,                -- دقائق الإضافي الليلي
  WAdd            INTEGER Default 0,                -- دقائق الإضافي نهاية الاسبوع
  HAdd            INTEGER Default 0,                -- دقائق الإضافي عطلة
  NAddAmt         NUMERIC(25,3) Default 0,             -- قيمة الإضافي الليلي
  DAddAmt         NUMERIC(25,3) Default 0,             -- قيمة الإضافي النهاري
  WAddAmt         NUMERIC(25,3) Default 0,             -- قيمة الإضافي عطلة نهاية الاسبوع
  HAddAmt         NUMERIC(25,3) Default 0,             -- قيمة الإضافي عطلة
  DelsPrice       NUMERIC(7,3) Default 0,              -- نسبة ساعة الغياب
  AbsPrice        NUMERIC(7,3) Default 0,              -- نسبة ساعة التأخير
  nDels           INTEGER Default 0,                -- دقائق التأخير
  nAbs            INTEGER Default 0,                -- دقائق الغياب
  nSick           INTEGER Default 0,                -- دقائق المرض
  nSick70         INTEGER Default 0,                -- دقائق المرض
  nSick80         INTEGER Default 0,                -- دقائق المرض
  nPar            INTEGER Default 0,                -- دقائق الأمومة
  nNPay           INTEGER Default 0,                -- دقائق دون أجر
  DelAmt          NUMERIC(25,3) Default 0,             -- قيمة التأخير
  AbsAmt          NUMERIC(25,3) Default 0,             -- قيمة الغياب
  SickAmt         NUMERIC(25,3) Default 0,             -- قيمة المرض
  SickAmt70       NUMERIC(25,3) Default 0,             -- قيمة المرض
  SickAmt80       NUMERIC(25,3) Default 0,             -- قيمة المرض
  ParAmt          NUMERIC(25,3) Default 0,             -- قيمة الأمومة
  NPayAmt         NUMERIC(25,3) Default 0,             -- قيمة دون أجر
  Rem             VARCHAR(250),                  -- ملاحظات
  Ins_User        BIGINT, Ins_Date   TIMESTAMP,
  Upd_User        BIGINT, Upd_Date   TIMESTAMP,
  Constraint      Emp_SalCalc_PK      Primary Key (Id),
  Constraint      Emp_SalCalc_UK      UNIQUE      (Sal_Id, Session_Id, Emp_Id)
);

